{"content": "from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient
import pytest

app = FastAPI()
call_count = 0

def my_dependency():
    global call_count
    call_count += 1
    return True

@app.get("/")
async def root(dep=Depends(my_dependency, scope="function")):
    return {"call_count": call_count}

client = TestClient(app)

def test_scope_function_paramless():
    global call_count
    call_count = 0

    # First request
    response1 = client.get("/")
    assert response1.json() == {"call_count": 1}

    # Second request
    response2 = client.get("/")
    assert response2.json() == {"call_count": 2}

if __name__ == "__main__":
    test_scope_function_paramless()
    print("Test passed!")
